//! midstudy's contract as Rust types: every JSON payload of the HTTP API (`contract/api/*.schema.json`) and every
//! file (`contract/*.schema.json`), generated by typify from `schema.json`, the bundle `scripts/gen-contract.mjs`
//! writes. Type names are the schemas' (`SceneObject`, `LibraryItem`, `Camera`, …): see `contract/api/README.md`.
//!
//! The types are as loose as `contract/gen/types.ts` (validation-only rules such as patterns, ranges and keys that
//! must be absent are left to the validators in `contract/gen/validate.js`), except that typify checks string
//! patterns when it parses (`Slug`, the URLs of a scene).

#[allow(
    clippy::all,
    clippy::pedantic,
    clippy::nursery,
    clippy::restriction,
    missing_debug_implementations,
    unused_qualifications,
    reason = "generated by typify (it compiles its pattern regexes with unwrap)"
)]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/types.rs"));
}

pub use generated::*;
